import math

def shipping_cost(kg: float) -> float:
    """Flat $5.00 up to 1 kg, then $2.00 per additional started kg."""
    if kg <= 1:
        return 5.0
    # additional started kg beyond the first
    return 5.0 + 2.0 * math.ceil(kg - 1)

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def _key(v: str):
        parts = v.split(".")
        # Pad missing parts with zeros to avoid IndexError
        while len(parts) < 3:
            parts.append("0")
        return tuple(int(p.lstrip("0") or "0") for p in parts[:3])
    return sorted(vs, key=_key)

