def sentiment(text: str) -> float:
    """Sentiment score in [-1, 1] from the trained model at models/sentiment_v3.pkl, rounded to 3 decimals."""
    if not isinstance(text, str):
        raise TypeError('Input must be a string')
    if _MODEL is None:
        raise RuntimeError('Model not loaded')
    # Assume the model has a predict_proba or predict method returning a score
    try:
        # Some models return array of probabilities for classes; take positive class
        if hasattr(_MODEL, 'predict_proba'):
            probs = _MODEL.predict_proba([text])[0]
            # Assume class 1 is positive
            score = probs[1] * 2 - 1
        else:
            score = _MODEL.predict([text])[0]
    except Exception as e:
        raise RuntimeError(f'Prediction failed: {e}')
    return round(float(score), 3)

