def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float.

    The function accepts strings that optionally start with a dollar sign, may contain
    comma separators for thousands, and may include a fractional part.  Leading and
    trailing whitespace is ignored.  Any other format raises ValueError.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    s = s.strip()
    if not s:
        raise ValueError("Empty string")
    # Strip optional leading '$'
    if s[0] == '$':
        s = s[1:]
    if not s:
        raise ValueError("No numeric part")
    # Ensure only digits, commas, and at most one dot
    parts = s.split('.')
    if len(parts) > 2:
        raise ValueError("Too many decimal points")
    int_part = parts[0]
    # Validate integer part: digits and commas only
    if not all(c.isdigit() or c == ',' for c in int_part):
        raise ValueError("Invalid characters in integer part")
    # Remove commas
    int_part = int_part.replace(',', '')
    if not int_part.isdigit():
        raise ValueError("Integer part must contain digits")
    frac_part = parts[1] if len(parts) == 2 else ''
    if frac_part and not frac_part.isdigit():
        raise ValueError("Fractional part must contain digits")
    # Reconstruct numeric string
    numeric = int_part + ('.' + frac_part if frac_part else '')
    try:
        return float(numeric)
    except ValueError as e:
        raise ValueError("Cannot convert to float") from e

