import sqlite3
import os

def customer_tier(customer_id: int) -> str:
    """Return the loyalty tier ('bronze'/'silver'/'gold') of a customer from the customers table in db/crm.sqlite."""
    db_path = os.path.join('db', 'crm.sqlite')
    if not os.path.isfile(db_path):
        # If the database file is missing, return a default value
        return 'unknown'
    try:
        conn = sqlite3.connect(db_path)
        cur = conn.cursor()
        cur.execute("SELECT tier FROM customers WHERE customer_id = ?", (customer_id,))
        row = cur.fetchone()
        conn.close()
        if row and row[0]:
            return str(row[0]).lower()
        return 'unknown'
    except Exception:
        return 'unknown'

