def normalize_phone(s: str) -> str:
    """Normalize a US phone number to the form (XXX) XXX-XXXX or XXX-XXX-XXXX based on input style."""
    # Extract digits
    digits = ''.join(ch for ch in s if ch.isdigit())
    if len(digits) != 10:
        raise ValueError("Phone number must contain 10 digits")
    area, prefix, line = digits[:3], digits[3:6], digits[6:]
    if '(' in s:
        # Input used parentheses; return without them, with dashes
        return f"{area}-{prefix}-{line}"
    else:
        # Return standard parentheses format
        return f"({area}) {prefix}-{line}"

