import datetime
import pathlib

def _load_holidays() -> set:
    """Load holiday dates from calendars/company_2025.ics and return a set of date strings.
    If the file is missing or malformed, return an empty set.
    """
    path = pathlib.Path(__file__).resolve().parent.parent / "calendars" / "company_2025.ics"
    if not path.is_file():
        return set()
    holidays = set()
    try:
        with path.open("r", encoding="utf-8") as f:
            lines = f.readlines()
    except Exception:
        return set()
    current_start = None
    for line in lines:
        line = line.strip()
        if line.upper().startswith("DTSTART"):
            # DTSTART;VALUE=DATE:20250704 or DTSTART:2025-07-04
            parts = line.split(":", 1)
            if len(parts) == 2:
                date_part = parts[1]
                try:
                    # support both yyyymmdd and iso
                    if len(date_part) == 8 and date_part.isdigit():
                        d = datetime.datetime.strptime(date_part, "%Y%m%d").date()
                    else:
                        d = datetime.datetime.fromisoformat(date_part).date()
                    holidays.add(d.isoformat())
                except Exception:
                    continue
    return holidays

